// image_symbols.h — stub symbol table for the iOS build.
// The real version is generated by the recompiler from default.xbe.
// All addresses are 0 (or small stub values) until a real recompile is done.
// Boot() validates X86EntryPoint before running, so a wrong XBE is caught early.
#pragma once
#include <cstdint>

